/* @lc app=leetcode id=2025 lang=kotlin */
class Solution { fun waysToPartition(nums: IntArray, k: Int): Int = nums.map { it.toLong() }.run { LongArray(1).let { p -> map { x -> (p[0] + x).also { p[0] = it } } }.let { pref -> pref.last().let { total -> mutableMapOf<Long, Int>().apply { (0 until size - 1).forEach { i -> put(pref[i], getOrDefault(pref[i], 0) + 1) } }.let { suff -> mutableMapOf<Long, Int>().let { pre -> (0 until size).fold(if (total % 2 == 0L) (suff[total / 2] ?: 0) else 0) { maxW, i -> (k.toLong() - get(i)).let { d -> (total + d).let { ns -> (if (ns % 2 == 0L) (pre[ns / 2] ?: 0) + (suff[ns / 2 - d] ?: 0) else 0).let { curW -> maxOf(maxW, curW).also { if (i < size - 1) suff.put(pref[i], (suff[pref[i]] ?: 0) - 1).also { pre.put(pref[i], (pre[pref[i]] ?: 0) + 1) } } } } } } } } } } }